[CmdletBinding()]
param(
  [Parameter(Mandatory)][string]$StageRoot,
  [Parameter(Mandatory)][string]$PlanPath,
  [Parameter(Mandatory)][string]$OutputPath
)
$ErrorActionPreference='Stop';$ProgressPreference='SilentlyContinue'
function Require([bool]$ok,[string]$m){if(-not $ok){throw "r12 source controls rejected: $m"}}
function Read-BoundedJson([string]$p){$i=Get-Item -LiteralPath $p -Force;Require (-not $i.PSIsContainer -and (($i.Attributes -band [IO.FileAttributes]::ReparsePoint)-eq 0) -and $i.Length -le 2097152) "bounded JSON rejected: $p";return [IO.File]::ReadAllText($i.FullName)|ConvertFrom-Json}
function Hash([string]$p){return (Get-FileHash -LiteralPath $p -Algorithm SHA256).Hash.ToLowerInvariant()}
function Parse-PS([string]$p){$t=$null;$e=$null;[void][Management.Automation.Language.Parser]::ParseFile($p,[ref]$t,[ref]$e);Require ($e.Count -eq 0) "PowerShell parse failed: $p"}
$stage=[IO.Path]::GetFullPath($StageRoot);$plan=Read-BoundedJson ([IO.Path]::GetFullPath($PlanPath));Require ([string]$plan.schema -eq 'sr0-display-selfjob-v4-fresh-one-run-r12') 'r12 plan schema mismatch';Require ([int]$plan.nativeActions -eq 0 -and [bool]$plan.qualificationClaim -eq $false) 'native/qualification flags invalid'
$collector=[IO.Path]::GetFullPath([string]$plan.collectorPath);$identity=[IO.Path]::GetFullPath([string]$plan.identityHelperPath);$drainHelper=[IO.Path]::GetFullPath([string]$plan.drainHelperPath);$collectorControl=[IO.Path]::GetFullPath((Join-Path $stage 'source-controls/test-collector-v8-source-controls-r11.ps1'));$control=[IO.Path]::GetFullPath((Join-Path $stage 'test-workload-drain-controls-r10.ps1'));$runner=[IO.Path]::GetFullPath((Join-Path $stage 'run-source-controls-r11.ps1'));foreach($p in @($collector,$identity,$drainHelper,$collectorControl,$control,$runner)){Require (Test-Path -LiteralPath $p -PathType Leaf) "control source missing: $p";Require ((Get-Item -LiteralPath $p -Force).Length -le 64MB) "control source exceeds bound: $p"}
Parse-PS $collector;Parse-PS $identity;Parse-PS $drainHelper;Parse-PS $collectorControl;Parse-PS $control;Require ((Hash $collector) -ceq ([string]$plan.sourcePins.collector).ToLowerInvariant()) 'new collector SHA mismatch';Require ((Hash $identity) -ceq ([string]$plan.sourcePins.identityHelper).ToLowerInvariant()) 'new identity SHA mismatch';Require ((Hash $drainHelper) -ceq ([string]$plan.sourcePins.drainHelper).ToLowerInvariant()) 'drain helper SHA mismatch';Require ((Hash $collectorControl) -ceq ([string]$plan.sourcePins.controlTestCollector).ToLowerInvariant()) 'collector control SHA mismatch';Require ((Hash $control) -ceq ([string]$plan.sourcePins.drainControlTestSha256).ToLowerInvariant()) 'drain control test SHA mismatch';$out=[IO.Path]::GetFullPath($OutputPath);Require (-not(Test-Path -LiteralPath $out)) 'controls output must be fresh';$outParent=Split-Path -Parent $out;$collectorControlOut=Join-Path $outParent 'collector-controls-r12.json';Require (-not(Test-Path -LiteralPath $collectorControlOut)) 'collector controls output must be fresh';$work=Join-Path $outParent 'drain-controls-work-r12';if(-not(Test-Path -LiteralPath $work)){[IO.Directory]::CreateDirectory($work)|Out-Null}
& $collectorControl -SourcePath $collector -OutputPath $collectorControlOut
Require ($? -eq $true) 'collector source controls failed';$collectorReceipt=Read-BoundedJson $collectorControlOut;Require ([string]$collectorReceipt.kind -eq 'sr0-display-collector-v8-source-controls' -and [string]$collectorReceipt.status -eq 'passed-source-controls' -and [bool]$collectorReceipt.nativeQualificationClaim -eq $false) 'collector source controls receipt invalid';& $control -DrainHelperPath $drainHelper -DrainHelperSha256 ([string]$plan.sourcePins.drainHelper) -OutputPath $out -WorkRoot $work
Require ($? -eq $true) 'drain controls failed';$receipt=Read-BoundedJson $out;Require ([string]$receipt.kind -eq 'sr0-display-workload-drain-controls-r10' -and [string]$receipt.status -eq 'passed-source-controls' -and [bool]$receipt.nativeQualificationClaim -eq $false) 'drain controls receipt invalid';$receipt|ConvertTo-Json -Depth 8
